Definition FFIELD_STACK : Z := 48 + FFIND_STACK.   (* [comment removed for export] *)

Definition ffield_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' r,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' res [C8 (wz r)]
    /\ AFieldsC m' Fa S L ns ls em /\ FT m'
    /\ ((r = Fa + 32 /\ ~ has_eqv key_lt (key_of em) (zbytes (ft_nameb f)) S)
        \/ (exists d, em !! r = Some d /\ r ∈ L /\ ieq (zbytes (ft_nameb f)) (zbytes (el_name d)) = true))
    /\ ACONST m' /\ stack0 m' lo shi.

Definition ffield_stmt : Prop := forall (res Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFieldsC m Fa S L ns ls em -> FT m -> (1 <= f < 130)%nat ->
  rw_cells bsegs m res [CB 8 rj] -> (res + 8 <= lo \/ bv_unsigned sp <= res) ->         (* [comment removed for export] *)
  stk bsegs m lo (bv_unsigned sp) -> lo + FFIELD_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  res mod 8 = 0 -> accessible m res 8 -> awin (res, res + 8) -> fwin Fa em (res, res + 8) ->
  (res + 8 <= AG_FIELD_TABLE \/ AG_FIELD_TABLE + 3456 <= res) ->
  (* [comment removed for export] *)
  0 < res ->
  evt bsegs (ffield_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res Fa f S L ns ls em lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz Fa) (wz (Z.of_nat f)) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_FIND_F) fc None m (seg_rom bsegs)).
