Lemma ValCells_value_bytes : forall m v d, rw_cells bsegs m v (ValCells d) ->
  bytes_at bsegs m (v + 10 + zlength (el_name d)) (el_value d).
Proof.
  intros m v d H.
  pose proof H as [[WF _] _]. cbn in WF. destruct WF as (_ & _ & _ & LP & _).
  pose proof (rw_cells_bytes_at _ _ _ _ H) as B. unfold ValCells in B.
  cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite LP in B.
  apply bytes_at_app in B. destruct B as [_ B].
  apply bytes_at_app in B. destruct B as [_ B]. cbn [length] in B.
  apply bytes_at_app in B. destruct B as [B _].
  unfold zlength. replace (v + 10 + Z.of_nat (length (el_name d))) with
    (v + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat (length (el_name d)) + Z.of_nat 2) by lia. exact B.
Qed.

Definition FINDEX_STACK : Z := 32 + FFIELD_STACK.   (* [comment removed for export] *)

Definition findex_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' vp vbs,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz vp) (wz (zlength vbs)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ AFieldsC m' Fa S L ns ls em /\ FT m'
    /\ bytes_at bsegs m' vp vbs
    /\ ((vp = 0 /\ vbs = [] /\ ~ has_eqv key_lt (key_of em) (zbytes (ft_nameb f)) S)
        \/ (exists r d, em !! r = Some d /\ r ∈ L /\ ieq (zbytes (ft_nameb f)) (zbytes (el_name d)) = true
                        /\ vbs = el_value d /\ vp = r + 58 + zlength (el_name d) /\ 0 < r /\ r + esize d <= aceil))
    /\ ACONST m' /\ stack0 m' lo shi.

Definition findex_stmt : Prop := forall (Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFieldsC m Fa S L ns ls em -> FT m -> (1 <= f < 130)%nat ->
  stk bsegs m lo (bv_unsigned sp) -> lo + FINDEX_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (findex_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa f S L ns ls em lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz Fa) (wz (Z.of_nat f)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_INDEX_F) fc None m (seg_rom bsegs)).

